"""Execute a parsed query (see ``ast.py``) against CSV files. See SPEC.md.

The pipeline is: load the table, validate the query statically against the
header, filter with WHERE, group (if the query is grouped), filter with
HAVING, compute output rows, apply DISTINCT, sort, then apply LIMIT/OFFSET.
"""

import csv
import functools
import os
import re
from decimal import ROUND_HALF_UP, Decimal, InvalidOperation

from . import ast
from .errors import QueryError

AGGREGATES = {"COUNT", "SUM", "AVG", "MIN", "MAX"}

# Scalar function name -> (min args, max args or None for unlimited).
SCALARS = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}

_INT_RE = re.compile(r"-?[0-9]+")
_FLOAT_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")

_MISSING = object()


class Result:
    """The result of a query: output column names and rows of values."""

    def __init__(self, columns, rows):
        self.columns = columns
        self.rows = rows

    def __repr__(self):
        return "Result(columns={!r}, rows={!r})".format(self.columns, self.rows)

    def __eq__(self, other):
        if not isinstance(other, Result):
            return NotImplemented
        return self.columns == other.columns and self.rows == other.rows


# ---------------------------------------------------------------------------
# Tables


class Table:
    def __init__(self, header, rows):
        self.header = header
        self.rows = rows
        self._index = {}
        for i, name in enumerate(header):
            # A name that appears more than once is ambiguous (index None).
            key = name.lower()
            self._index[key] = None if key in self._index else i

    def index(self, name):
        key = name.lower()
        if key not in self._index:
            raise QueryError("unknown column: {}".format(name))
        i = self._index[key]
        if i is None:
            raise QueryError("ambiguous column: {}".format(name))
        return i


def convert_field(text):
    if text == "":
        return None
    if _INT_RE.fullmatch(text):
        return int(text)
    if _FLOAT_RE.fullmatch(text):
        return float(text)
    return text


def load_table(directory, name):
    if not name or "/" in name or os.sep in name or name in (".", ".."):
        raise QueryError("unknown table: {}".format(name))
    path = os.path.join(directory, name + ".csv")
    try:
        with open(path, newline="", encoding="utf-8") as f:
            records = list(csv.reader(f))
    except FileNotFoundError:
        raise QueryError("unknown table: {}".format(name))
    except (OSError, UnicodeDecodeError, csv.Error) as e:
        raise QueryError("cannot read table {}: {}".format(name, e))
    if not records:
        return Table([], [])
    header = records[0]
    rows = []
    for line, record in enumerate(records[1:], start=2):
        if not record:
            continue  # blank line
        if len(record) > len(header):
            raise QueryError(
                "{}.csv line {}: too many fields".format(name, line))
        values = [convert_field(field) for field in record]
        values.extend([None] * (len(header) - len(values)))
        rows.append(tuple(values))
    return Table(header, rows)


# ---------------------------------------------------------------------------
# Values


def kind(value):
    """The comparison class of a non-NULL value: "bool", "number" or "string"."""
    if isinstance(value, bool):
        return "bool"
    if isinstance(value, (int, float)):
        return "number"
    return "string"


def is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def value_key(value):
    """A hashable key under which equal SQL values (and only those) collide.

    Python treats True == 1, so tag booleans separately; ints and floats
    share a tag because they compare numerically.
    """
    if value is None:
        return ("null",)
    return (kind(value), value)


def compare(a, b):
    """Compare two non-NULL values: -1, 0 or 1. Mixed types are an error."""
    ka, kb = kind(a), kind(b)
    if ka != kb:
        raise QueryError("cannot compare {} with {}".format(
            describe(a), describe(b)))
    return (a > b) - (a < b)


def describe(value):
    if value is None:
        return "NULL"
    return "{} {}".format(kind(value), format_value(value, quote=True))


def format_value(value, quote=False):
    """Text of a value, as used by ``||`` and the CSV output."""
    if value is None:
        return ""
    if value is True:
        return "true"
    if value is False:
        return "false"
    if quote and isinstance(value, str):
        return "'" + value.replace("'", "''") + "'"
    return str(value)


def check_bool(value, what):
    if value is not None and not isinstance(value, bool):
        raise QueryError("{} needs a boolean, got {}".format(what, describe(value)))
    return value


# ---------------------------------------------------------------------------
# Expression structure


def children(expr):
    if isinstance(expr, ast.Unary):
        return [expr.operand]
    if isinstance(expr, ast.Binary):
        return [expr.left, expr.right]
    if isinstance(expr, ast.IsNull):
        return [expr.operand]
    if isinstance(expr, ast.In):
        return [expr.operand] + list(expr.items)
    if isinstance(expr, ast.Between):
        return [expr.operand, expr.low, expr.high]
    if isinstance(expr, ast.Like):
        return [expr.operand, expr.pattern]
    if isinstance(expr, ast.Call):
        return list(expr.args)
    return []


def expr_key(expr):
    """A hashable structural key: equal for expressions that mean the same.

    Column names compare case-insensitively, and literals compare by SQL
    value (so TRUE and 1 differ).
    """
    if isinstance(expr, ast.Literal):
        return ("lit", value_key(expr.value), type(expr.value).__name__)
    if isinstance(expr, ast.Column):
        return ("col", expr.name.lower())
    extra = ()
    if isinstance(expr, (ast.Unary, ast.Binary)):
        extra = (expr.op,)
    elif isinstance(expr, (ast.IsNull, ast.In, ast.Between, ast.Like)):
        extra = (expr.negated,)
    elif isinstance(expr, ast.Call):
        extra = (expr.name, expr.star)
    return (type(expr).__name__,) + extra + tuple(expr_key(c) for c in children(expr))


def is_aggregate(expr):
    return isinstance(expr, ast.Call) and expr.name in AGGREGATES


def contains_aggregate(expr):
    return is_aggregate(expr) or any(contains_aggregate(c) for c in children(expr))


# ---------------------------------------------------------------------------
# Static validation


def validate(expr, table, clause, inside_aggregate=False):
    """Check column names, functions and aggregate placement in ``expr``."""
    if isinstance(expr, ast.Column):
        table.index(expr.name)
        return
    if isinstance(expr, ast.Call):
        if expr.name in AGGREGATES:
            if clause is not None:
                raise QueryError("aggregate {} not allowed in {}".format(
                    expr.name, clause))
            if inside_aggregate:
                raise QueryError("aggregates can't be nested: {}".format(expr.name))
            if expr.star:
                if expr.name != "COUNT":
                    raise QueryError("{}(*) is not allowed".format(expr.name))
            elif len(expr.args) != 1:
                raise QueryError("{} takes 1 argument".format(expr.name))
            inside_aggregate = True
        elif expr.name in SCALARS:
            low, high = SCALARS[expr.name]
            n = len(expr.args)
            if expr.star or n < low or (high is not None and n > high):
                raise QueryError("wrong number of arguments to {}".format(expr.name))
        else:
            raise QueryError("unknown function: {}".format(expr.name))
    for child in children(expr):
        validate(child, table, clause, inside_aggregate)


def check_grouped(expr, group_keys):
    """In a grouped query, columns must be inside aggregates or GROUP BY exprs."""
    if expr_key(expr) in group_keys or is_aggregate(expr):
        return
    if isinstance(expr, ast.Column):
        raise QueryError(
            "column {} must appear in GROUP BY or be used in an aggregate".format(
                expr.name))
    for child in children(expr):
        check_grouped(child, group_keys)


# ---------------------------------------------------------------------------
# Evaluation


class RowContext:
    """Evaluates column references against a single input row."""

    def __init__(self, table, row):
        self.table = table
        self.row = row

    def lookup(self, expr):
        if isinstance(expr, ast.Column):
            return self.row[self.table.index(expr.name)]
        return _MISSING


class GroupContext:
    """Evaluates GROUP BY expressions and aggregates against a group of rows."""

    def __init__(self, table, group_keys, key_values, rows):
        self.table = table
        self.group_keys = group_keys  # expr_key -> position in key_values
        self.key_values = key_values
        self.rows = rows

    def lookup(self, expr):
        position = self.group_keys.get(expr_key(expr))
        if position is not None:
            return self.key_values[position]
        if is_aggregate(expr):
            return aggregate(expr, self.table, self.rows)
        return _MISSING


def evaluate(expr, ctx):
    value = ctx.lookup(expr)
    if value is not _MISSING:
        return value
    if isinstance(expr, ast.Literal):
        return expr.value
    if isinstance(expr, ast.Column):
        # Unreachable after validation; kept as a safety net.
        raise QueryError("column {} can't be used here".format(expr.name))
    if isinstance(expr, ast.Unary):
        return eval_unary(expr.op, evaluate(expr.operand, ctx))
    if isinstance(expr, ast.Binary):
        return eval_binary(expr.op, evaluate(expr.left, ctx),
                           evaluate(expr.right, ctx))
    if isinstance(expr, ast.IsNull):
        return (evaluate(expr.operand, ctx) is None) != expr.negated
    if isinstance(expr, ast.In):
        result = eval_in(evaluate(expr.operand, ctx),
                         [evaluate(item, ctx) for item in expr.items])
        return negate(result, expr.negated)
    if isinstance(expr, ast.Between):
        x = evaluate(expr.operand, ctx)
        low = evaluate(expr.low, ctx)
        high = evaluate(expr.high, ctx)
        result = logical_and(eval_binary("<=", low, x), eval_binary("<=", x, high))
        return negate(result, expr.negated)
    if isinstance(expr, ast.Like):
        result = eval_like(evaluate(expr.operand, ctx), evaluate(expr.pattern, ctx))
        return negate(result, expr.negated)
    if isinstance(expr, ast.Call):
        if expr.name in AGGREGATES:
            raise QueryError("aggregate {} can't be used here".format(expr.name))
        return call_scalar(expr.name, [evaluate(a, ctx) for a in expr.args])
    raise QueryError("unsupported expression: {!r}".format(expr))


def negate(value, negated):
    if negated and value is not None:
        return not value
    return value


def logical_and(a, b):
    check_bool(a, "AND")
    check_bool(b, "AND")
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def logical_or(a, b):
    check_bool(a, "OR")
    check_bool(b, "OR")
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def eval_unary(op, value):
    if op == "NOT":
        check_bool(value, "NOT")
        return None if value is None else not value
    if op == "-":
        if value is None:
            return None
        if not is_number(value):
            raise QueryError("can't negate {}".format(describe(value)))
        return -value
    raise QueryError("unknown operator: {}".format(op))


_COMPARISONS = {
    "=": lambda c: c == 0,
    "!=": lambda c: c != 0,
    "<": lambda c: c < 0,
    "<=": lambda c: c <= 0,
    ">": lambda c: c > 0,
    ">=": lambda c: c >= 0,
}


def eval_binary(op, a, b):
    if op == "AND":
        return logical_and(a, b)
    if op == "OR":
        return logical_or(a, b)
    if a is None or b is None:
        return None
    if op in _COMPARISONS:
        return _COMPARISONS[op](compare(a, b))
    if op == "||":
        return format_value(a) + format_value(b)
    if op in ("+", "-", "*", "/"):
        return arithmetic(op, a, b)
    raise QueryError("unknown operator: {}".format(op))


def arithmetic(op, a, b):
    if not (is_number(a) and is_number(b)):
        raise QueryError("can't apply {} to {} and {}".format(
            op, describe(a), describe(b)))
    try:
        if op == "/":
            if b == 0:
                return None
            return a / b
        if op == "+":
            result = a + b
        elif op == "-":
            result = a - b
        else:
            result = a * b
    except OverflowError:
        raise QueryError("numeric overflow in {}".format(op))
    if isinstance(a, int) and isinstance(b, int):
        return result
    return float(result)


def eval_in(x, items):
    if x is None:
        return None
    found = False
    saw_null = False
    for item in items:
        if item is None:
            saw_null = True
        elif compare(x, item) == 0:
            found = True
    if found:
        return True
    return None if saw_null else False


@functools.lru_cache(maxsize=256)
def like_regex(pattern):
    parts = []
    for ch in pattern:
        if ch == "%":
            parts.append(".*")
        elif ch == "_":
            parts.append(".")
        else:
            parts.append(re.escape(ch))
    return re.compile("".join(parts), re.DOTALL)


def eval_like(value, pattern):
    if value is None or pattern is None:
        return None
    if not (isinstance(value, str) and isinstance(pattern, str)):
        raise QueryError("LIKE needs strings, got {} and {}".format(
            describe(value), describe(pattern)))
    return like_regex(pattern).fullmatch(value) is not None


# ---------------------------------------------------------------------------
# Functions


def call_scalar(name, args):
    if name == "COALESCE":
        for arg in args:
            if arg is not None:
                return arg
        return None
    if any(arg is None for arg in args):
        return None
    if name in ("LOWER", "UPPER", "LENGTH"):
        (s,) = args
        if not isinstance(s, str):
            raise QueryError("{} needs a string, got {}".format(name, describe(s)))
        if name == "LOWER":
            return s.lower()
        if name == "UPPER":
            return s.upper()
        return len(s)
    if name == "ABS":
        (x,) = args
        if not is_number(x):
            raise QueryError("ABS needs a number, got {}".format(describe(x)))
        return abs(x)
    if name == "ROUND":
        return round_half_away(*args)
    raise QueryError("unknown function: {}".format(name))


def round_half_away(x, places=_MISSING):
    """ROUND(x) -> int; ROUND(x, n) -> float. Halves round away from zero.

    Rounds the shortest decimal representation of ``x`` (its repr), so
    ROUND(1.005, 2) is 1.01 as written rather than 1.0 from binary error.
    """
    if not is_number(x):
        raise QueryError("ROUND needs a number, got {}".format(describe(x)))
    if places is _MISSING:
        if isinstance(x, int):
            return x
        try:
            return int(Decimal(repr(x)).quantize(Decimal(1), rounding=ROUND_HALF_UP))
        except (InvalidOperation, ValueError, OverflowError):
            raise QueryError("can't round {}".format(describe(x)))
    if not (is_number(places) and isinstance(places, int)):
        raise QueryError("ROUND places must be an integer, got {}".format(
            describe(places)))
    exponent = Decimal(1).scaleb(-places)
    try:
        return float(Decimal(repr(x)).quantize(exponent, rounding=ROUND_HALF_UP))
    except InvalidOperation:
        # Too many places for Decimal's precision: nothing to round.
        return float(x)


def aggregate(expr, table, rows):
    name = expr.name
    if expr.star:
        return len(rows)
    arg = expr.args[0]
    values = [evaluate(arg, RowContext(table, row)) for row in rows]
    values = [v for v in values if v is not None]
    if name == "COUNT":
        return len(values)
    if not values:
        return None
    if name in ("SUM", "AVG"):
        for v in values:
            if not is_number(v):
                raise QueryError("{} needs numbers, got {}".format(name, describe(v)))
        if name == "AVG":
            return float(sum(values)) / len(values) if all(
                isinstance(v, int) for v in values) else sum(values) / len(values)
        total = sum(values)
        return total if all(isinstance(v, int) for v in values) else float(total)
    # MIN / MAX
    best = values[0]
    for v in values[1:]:
        c = compare(v, best)
        if (name == "MIN" and c < 0) or (name == "MAX" and c > 0):
            best = v
    return best


# ---------------------------------------------------------------------------
# Query execution


def execute(query, directory):
    """Run a parsed ``ast.Query`` against CSV files in ``directory``."""
    table = load_table(directory, query.table)

    # Output columns: (expression, name).
    if query.columns is None:
        items = [(ast.Column(name), name) for name in table.header]
    else:
        items = []
        for item in query.columns:
            if item.alias is not None:
                name = item.alias
            elif isinstance(item.expr, ast.Column):
                name = table.header[table.index(item.expr.name)]
            else:
                name = item.text
            items.append((item.expr, name))
    names = [name for _, name in items]

    # ORDER BY items resolve to ("output", index) or ("expr", expression).
    order = [resolve_order_item(o, names) for o in query.order_by]
    order_exprs = [target for kind_, target in order if kind_ == "expr"]

    # Static validation.
    if query.where is not None:
        validate(query.where, table, "WHERE")
    for expr in query.group_by:
        validate(expr, table, "GROUP BY")
    for expr, _ in items:
        validate(expr, table, None)
    if query.having is not None:
        validate(query.having, table, None)
    for expr in order_exprs:
        validate(expr, table, None)
    for value, what in ((query.limit, "LIMIT"), (query.offset, "OFFSET")):
        if value is not None and (not isinstance(value, int) or
                                  isinstance(value, bool) or value < 0):
            raise QueryError("{} must be a non-negative integer".format(what))

    group_level = [expr for expr, _ in items] + order_exprs
    if query.having is not None:
        group_level.append(query.having)
    grouped = (bool(query.group_by) or query.having is not None or
               any(contains_aggregate(e) for e in group_level))
    group_keys = {}
    if grouped:
        for position, expr in enumerate(query.group_by):
            group_keys.setdefault(expr_key(expr), position)
        for expr in group_level:
            check_grouped(expr, group_keys)

    # WHERE.
    rows = table.rows
    if query.where is not None:
        rows = [row for row in rows
                if condition(query.where, RowContext(table, row), "WHERE")]

    # Contexts in which output expressions are evaluated: one per row or group.
    if grouped:
        contexts = [GroupContext(table, group_keys, key_values, group_rows)
                    for key_values, group_rows in make_groups(query, table, rows)]
        if query.having is not None:
            contexts = [ctx for ctx in contexts
                        if condition(query.having, ctx, "HAVING")]
    else:
        contexts = [RowContext(table, row) for row in rows]

    # Output rows, each paired with the expression-based sort values it needs.
    results = []
    for ctx in contexts:
        out = tuple(evaluate(expr, ctx) for expr, _ in items)
        extra = [evaluate(expr, ctx) for expr in order_exprs]
        results.append((out, extra))

    if query.distinct:
        seen = set()
        unique = []
        for out, extra in results:
            key = tuple(value_key(v) for v in out)
            if key not in seen:
                seen.add(key)
                unique.append((out, extra))
        results = unique

    if order:
        results = sort_results(results, order, [o.descending for o in query.order_by])

    output = [out for out, _ in results]
    start = query.offset or 0
    end = None if query.limit is None else start + query.limit
    return Result(names, output[start:end])


def resolve_order_item(item, names):
    expr = item.expr
    if isinstance(expr, ast.Column):
        lowered = expr.name.lower()
        for i, name in enumerate(names):
            if name.lower() == lowered:
                return ("output", i)
    if (isinstance(expr, ast.Literal) and isinstance(expr.value, int)
            and not isinstance(expr.value, bool)):
        n = expr.value
        if not 1 <= n <= len(names):
            raise QueryError("ORDER BY position {} is out of range".format(n))
        return ("output", n - 1)
    return ("expr", expr)


def condition(expr, ctx, clause):
    return check_bool(evaluate(expr, ctx), clause) is True


def make_groups(query, table, rows):
    """Yield (key values, rows) per group, in order of each group's first row."""
    if not query.group_by:
        return [([], rows)]
    groups = {}
    for row in rows:
        ctx = RowContext(table, row)
        values = [evaluate(expr, ctx) for expr in query.group_by]
        key = tuple(value_key(v) for v in values)
        if key not in groups:
            groups[key] = (values, [])
        groups[key][1].append(row)
    return list(groups.values())


def sort_results(results, order, descending):
    """Stable sort by ORDER BY keys; NULLs first ascending, last descending."""

    def sort_values(result):
        out, extra = result
        values = []
        extra_iter = iter(extra)
        for kind_, target in order:
            values.append(out[target] if kind_ == "output" else next(extra_iter))
        return values

    def cmp(a, b):
        for x, y, desc in zip(a, b, descending):
            if x is None and y is None:
                c = 0
            elif x is None:
                c = -1
            elif y is None:
                c = 1
            else:
                c = compare(x, y)
            if c:
                return -c if desc else c
        return 0

    keyed = [(sort_values(r), r) for r in results]
    keyed.sort(key=functools.cmp_to_key(lambda a, b: cmp(a[0], b[0])))
    return [r for _, r in keyed]

